#include <Arduino.h>
#include "main.h"

// The Arduino contract: setup() runs once, loop() forever. The Rust templates split the same two halves into
// an Embassy main and a task, so a project of either language has one obvious place for "at power on" and
// one for "all the time".

void setup() {
    pinMode(4, OUTPUT);
    pinMode(17, OUTPUT);
    pinMode(16, OUTPUT);

    Serial.begin(115200);
    Serial.println("ESP32-035 LCD Panel: blinky ready");
}

void loop() {
    // One colour at a time, so a wrong wiring shows as a wrong colour rather than as nothing.
    static uint8_t step = 0;
    digitalWrite(4, step == 0);
    digitalWrite(17, step == 1);
    digitalWrite(16, step == 2);
    step = static_cast<uint8_t>((step + 1) % 3);
    delay(200);
}
